// Build the board feed from live GoHighLevel data.
const pipesResp = $('Get pipelines').first().json;
const pipelines = pipesResp.pipelines || [];
const gi = pipelines.find(p => (p.name || '').toLowerCase().includes('general inquiry')) || pipelines[0] || { stages: [] };
const stageName = {};
(gi.stages || []).forEach(s => { stageName[s.id] = (s.name || '').toLowerCase(); });

const usersResp = $('Get users').first().json;
const users = usersResp.users || [];
const nameByUser = {};
users.forEach(u => {
  const n = (u.name || [u.firstName, u.lastName].filter(Boolean).join(' ')).trim();
  if (n) nameByUser[u.id] = n;
});

const shortName = (full) => {
  const parts = String(full || '').trim().split(/\s+/).filter(Boolean);
  if (parts.length === 0) return 'Lead';
  if (parts.length === 1) return parts[0];
  return parts[0] + ' ' + parts[parts.length - 1][0] + '.';
};

// --- New Inquiries: General Inquiry pipeline, excluding Appointment Booked ---
const oppResp = $('Get opportunities').first().json;
const opps = (oppResp.opportunities || []).filter(o => o.pipelineId === gi.id);
const inquiries = [];
for (const o of opps) {
  const stage = stageName[o.pipelineStageId] || '';
  if (stage.includes('appointment')) continue; // booked -> not an inquiry
  inquiries.push({
    id: o.id,
    name: shortName(o.contact && o.contact.name ? o.contact.name : o.name),
    source: o.source || '—',
    receivedAt: o.createdAt,
    assignedTo: o.assignedTo ? (nameByUser[o.assignedTo] || 'Assigned') : null,
    attempts: 0
  });
}

// --- Appointments: calendar events (today + tomorrow window) ---
const evResp = $('Get appointments').first().json;
const events = evResp.events || [];
const skip = new Set(['cancelled', 'invalid']);
const appointments = [];
for (const e of events) {
  const st = (e.appointmentStatus || '').toLowerCase();
  if (skip.has(st)) continue;
  appointments.push({
    id: e.id,
    name: shortName(e.contactName || (e.contact && e.contact.name) || e.title),
    appointmentAt: e.startTime,
    interest: '',
    assignedTo: e.assignedUserId ? (nameByUser[e.assignedUserId] || 'Assigned') : null,
    confirmed: st === 'confirmed',
    arrived: st === 'showed'
  });
}

return [{ json: {
  inquiries,
  appointments,
  floor: [],
  generatedAt: new Date().toISOString(),
  stats: { inquiriesToday: inquiries.length }
} }];
